export const ORCHARD_ABILITIES=[{id:'ABILITY_STILLWATER',name:'Stillwater',text:'Every third direct special HP hit received after entry triggers three automatic 50-power special Water slashes. No PP/action cost. Counter resets on switching. No reply chains or replies after fainting.'},{id:'ABILITY_BERRY_PANTRY',name:'Berry Pantry',text:'At each turn end, if empty-handed, 25% chance to recover the last berry actually eaten; 75% in Grassy Terrain, including while Flying. Repeatable; one roll per turn. Stolen or removed berries do not count.'}];
export function installTideOrchard(data){
 if(data.tideOrchardVersion)return;data.tideOrchardVersion=1;
 data.species.push(...TIDE_ORCHARD_SPECIES);data.moves.push(...TIDE_ORCHARD_MOVES);
 for(const s of TIDE_ORCHARD_SPECIES){const cat=s.family_id==='FAMILY-518',cap=s.id==='515'?23:s.id==='516'?41:s.id==='518'?29:200;
 const learn=(level,key,method)=>{const id=ORCHARD_IDS[key],m=data.moves.find(m=>m.id===id);if(!m)throw Error('Missing Tide & Orchard move '+key);data.learnsets.push({species_id:s.id,move_id:id,name:m.name,level,method,tideOrchard:true,identity:true,identity_core:true});};
 for(const [level,key]of cat?CAT_LEVELS:RABBIT_LEVELS)if(level<=cap)learn(level,key,'LEVEL_UP');
 for(const key of cat?CAT_TUTORS:RABBIT_TUTORS){if(s.id==='518'&&['aromatherapy','stun','poison','worry'].includes(key))continue;learn(1,key,'CODEX');}
 data.assets.push({id:s.id,source:'art-library/tide-orchard/'+s.name.toLowerCase()+'.png',runtime:'assets/'+s.id+'.webp'});
 }
 data.authoredLearnsets?.push(...data.learnsets.filter(l=>l.tideOrchard).map(l=>structuredClone(l)));
 for(const m of TIDE_ORCHARD_MOVES){m.tutorTypes=[];m.codexOnly=true;m.effect_text=m.effect_text||'';}
}
